using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace Astrea.RunModifiers;

[CreateAssetMenu(fileName = "DiceShortageRunModifier", menuName = "Data/RunModifiers/DiceShortageRunModifier", order = 0)]
public class DiceShortageRunModifier : RunModifier
{
	public override void Initialize()
	{
		ReferenceSingleton<RunModifiersManager>.Instance.DiceShortageRunModifier = this;
	}

	public Reward[] GetBattleModifiedRewards(Reward[] nonModifiedRewards)
	{
		List<Reward> list = nonModifiedRewards.DuplicateAsList();
		switch (list.Count((Reward item) => item is DiceReward))
		{
		case 0:
			return nonModifiedRewards;
		case 2:
		{
			int num = list.FindIndex((Reward item) => item is DiceReward);
			list.RemoveAt(num + 1);
			break;
		}
		}
		return list.ToArray();
	}
}
